def sin_gate6fb(rel: str, txt: str) -> str:
    # Actualizado en el hotfix 6G-C de PREPROD-1: primero se deshacen EXACTAMENTE sus cambios
    from _base_preprod1_6gc import sin_preprod1_6gc
    txt = sin_preprod1_6gc(rel, txt)
    for clave, bl in _BLOQUES.items():
        if rel.replace("\\", "/").endswith(clave):
            if not all(txt.count(nuevo) == 1 for nuevo, _ in bl):
                return txt
            for nuevo, viejo in bl:
                txt = txt.replace(nuevo, viejo, 1)
            return txt
    return txt
